css:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

.print-format {
  margin: 5px !important;
  padding: 5px !important;
  width: 100% !important;
}

html, body {
  margin: 0 !important;
  padding: 0 !important;
  font-family: 'Helvetica', 'Arial', sans-serif;
  background-color: white;
  line-height: 1.4;
  font-size: 14px;
  color: #000;
}

.digitax-receipt {
  background-color: white;
  margin: 0;
  padding: 5px;
  width: 100%;
}

.receipt-header {
  margin-bottom: 20px;
}

.school-name {
  font-size: 22px;
  font-weight: bold;
  color: #000;
  margin-bottom: 10px;
  letter-spacing: 0.5px;
}

.receipt-content {
  display: flex;
  justify-content: flex-start;
  align-items: flex-start;
  gap: 40px;
  margin-bottom: 30px;
}

.receipt-info {
  flex: 1;
  max-width: 420px;
}

.info-row {
  display: flex;
  margin-bottom: 6px;
  align-items: flex-start;
}

.receipt-label {
  display: inline-block;
  width: 140px;
  font-weight: normal;
  font-size: 14px;
  text-align: left;
  vertical-align: top;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  padding: 0 !important;
}

.receipt-value {
  flex: 1;
  font-weight: bold;
  font-size: 14px;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  padding: 0 !important;
}

.right-section {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.school-logo img {
  width: 60px;
  height: auto;
  margin-bottom: 20px;
}

.signature-box {
  width: 75px;
  height: 80px;
  border: 1px solid #000;
  margin-top: 40px;
  margin-left: -70px;
  position: relative;
}

.signature-box::after {
  content: '';
  position: absolute;
  top: 80%;
  left: -30px;
  right: -30px;
  height: 1px;
  background-color: #000;
}

.doc-banner {
  margin-bottom: 12px;
}

.doc-type {
  font-size: 18px;
  font-weight: bold;
}

.doc-status {
  display: inline-block;
  margin-top: 4px;
  font-size: 12px;
  font-weight: bold;
  letter-spacing: 0.5px;
}

.section-block {
  margin-top: 24px;
}

.section-title {
  font-size: 15px;
  font-weight: bold;
  margin-bottom: 8px;
}

.items-table,
.tax-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 8px;
}

.items-table th,
.items-table td,
.tax-table th,
.tax-table td {
  border: 1px solid #ddd;
  padding: 6px 8px;
  font-size: 13px;
}

.items-table th,
.tax-table th {
  background: #f5f5f5;
  font-weight: bold;
}

.text-right {
  text-align: right;
}

.total-row {
  display: flex;
  justify-content: space-between;
  font-weight: bold;
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px solid #000;
}

.footer-block {
  margin-top: 30px;
  padding-top: 12px;
  border-top: 1px solid #ddd;
}

.footer-content {
  display: flex;
  justify-content: flex-start;
  align-items: flex-start;
  gap: 40px;
}

.footer-info {
  flex: 1;
  max-width: 420px;
}

.footer-qr {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.qr-label {
  font-size: 12px;
  margin-bottom: 8px;
}

.qr-image {
  width: 120px;
  height: 120px;
}

.notice-box {
  margin-top: 20px;
  padding: 12px;
  border: 1px solid #ccc;
}
